n.a=p
p+="```javascript\n"
n.a=p
p+="const items = await Aboutme.plugins.checkin.getCheckinItems(); const target = items.find(i => !i.isCheckedToday); if (!target) { const msg = '\u6240\u6709\u9879\u76ee\u4eca\u5929\u90fd\u5df2\u7b7e\u5230'; setResult(msg); return msg; } const result = await Aboutme.plugins.checkin.checkin(target.id); const msg = result.success ? `\u7b7e\u5230\u6210\u529f: ${target.name}` : result.message; setResult(msg); return msg;\n"
